import { useState, type FormEvent } from 'react';
import {
  JxAlert,
  JxButton,
  JxInputField,
  JxSelect,
  JxSwitch,
} from '@jinx-ui/react';

const ROLES = [
  { value: 'viewer', label: 'Наблюдатель', meta: 'только чтение' },
  { value: 'editor', label: 'Редактор', meta: 'правки и задачи' },
  { value: 'admin', label: 'Администратор', meta: 'полный доступ' },
];

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [touched, setTouched] = useState(false);
  const [role, setRole] = useState('editor');
  const [notify, setNotify] = useState(true);
  const [invited, setInvited] = useState<string | null>(null);

  const emailValid = EMAIL_PATTERN.test(email.trim());
  const errorText =
    touched && !emailValid
      ? email.trim().length === 0
        ? 'Укажите адрес почты'
        : 'Похоже, это не адрес почты. Пример: name@company.com'
      : undefined;

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setTouched(true);
    if (!emailValid) return;
    setInvited(email.trim());
    setEmail('');
    setTouched(false);
  };

  return (
    <div style={{ display: 'grid', gap: '16px', maxWidth: '420px' }}>
      {invited && (
        <JxAlert
          intent="success"
          title="Приглашение отправлено"
          role="status"
        >
          <span style={{ display: 'grid', gap: '8px', justifyItems: 'start' }}>
            <span>
              {invited} получил приглашение
              {notify ? ' и уведомление на почту.' : ' без уведомления на почту.'}
            </span>
            <JxButton
              variant="ghost"
              size="sm"
              onClick={() => setInvited(null)}
            >
              Закрыть
            </JxButton>
          </span>
        </JxAlert>
      )}

      <form onSubmit={submit} noValidate style={{ display: 'grid', gap: '16px' }}>
        <JxInputField
          label="Почта участника"
          type="email"
          required
          autoComplete="email"
          placeholder="name@company.com"
          value={email}
          onChange={(event) => setEmail(event.target.value)}
          onBlur={() => setTouched(true)}
          helperText="Рабочий адрес, на него придёт ссылка-приглашение"
          errorText={errorText}
        />

        <JxSelect
          label="Роль в команде"
          options={ROLES}
          value={role}
          onValueChange={setRole}
          placeholder="Выберите роль"
        />

        <JxSwitch
          label="Отправить уведомление на почту"
          checked={notify}
          onChange={(event) => setNotify(event.target.checked)}
        />

        <div style={{ display: 'flex', gap: '8px' }}>
          <JxButton type="submit" variant="primary" disabled={!emailValid}>
            Отправить приглашение
          </JxButton>
        </div>
      </form>
    </div>
  );
}

